// Nodo 3 — Parseo del XML de Nmap.
// Fix de hallazgos del dictamen: try/catch real, parseStringPromise
// (async, no callback), encadenamiento opcional en todo acceso a campos
// que pueden no existir (evita que un host "raro" tire abajo el nodo).
// v2: agrega los timestamps reales del escaneo (tomados del propio XML
// de Nmap, no de la hora de ejecución de n8n).

const { parseStringPromise } = require('xml2js');

const results = [];

for (const item of $input.all()) {
  const rawXml = item.json.stdout;

  if (!rawXml) {
    throw new Error('El item no contiene stdout con el XML de Nmap. Verificar el nodo Execute Command anterior.');
  }

  let parsed;
  try {
    parsed = await parseStringPromise(rawXml, { explicitArray: true });
  } catch (err) {
    results.push({
      json: {
        parseError: true,
        errorMessage: err.message,
        rawXmlSnippet: rawXml.slice(0, 200),
      },
    });
    continue;
  }

  // Timestamps reales del escaneo, tomados del propio Nmap (epoch en
  // segundos -> ISO 8601 para que Postgres los acepte sin conversión).
  const startEpoch = parsed?.nmaprun?.$?.start ?? null;
  const endEpoch = parsed?.nmaprun?.runstats?.[0]?.finished?.[0]?.$?.time ?? null;
  const scanStartedAt = startEpoch ? new Date(Number(startEpoch) * 1000).toISOString() : null;
  const scanFinishedAt = endEpoch ? new Date(Number(endEpoch) * 1000).toISOString() : null;

  const hosts = parsed?.nmaprun?.host ?? [];

  for (const host of hosts) {
    const address = host?.address?.[0]?.$?.addr ?? 'unknown';
    const hostname = host?.hostnames?.[0]?.hostname?.[0]?.$?.name ?? null;
    const hostStatus = host?.status?.[0]?.$?.state ?? 'unknown';
    const ports = host?.ports?.[0]?.port ?? [];

    if (ports.length === 0) {
      results.push({
        json: {
          parseError: false,
          hostIp: address,
          hostname,
          hostStatus,
          port: null,
          protocol: null,
          serviceName: null,
          serviceProduct: null,
          serviceVersion: null,
          scanStartedAt,
          scanFinishedAt,
        },
      });
      continue;
    }

    for (const port of ports) {
      const service = port?.service?.[0]?.$ ?? {};
      results.push({
        json: {
          parseError: false,
          hostIp: address,
          hostname,
          hostStatus,
          port: port?.$?.portid ?? null,
          protocol: port?.$?.protocol ?? null,
          portState: port?.state?.[0]?.$?.state ?? 'unknown',
          serviceName: service.name ?? null,
          serviceProduct: service.product ?? null,
          serviceVersion: service.version ?? null,
          serviceExtraInfo: service.extrainfo ?? null,
          scanStartedAt,
          scanFinishedAt,
        },
      });
    }
  }
}

return results;

// Nodo 4 — Preparar resumen para scan_history.
// Corre una sola vez sobre TODOS los items que produjo el Nodo 3 (parseo),
// y arma un único registro-resumen del escaneo completo.

const crypto = require('crypto');

const items = $input.all();

if (items.length === 0) {
  throw new Error('No hay items de entrada: el escaneo no produjo ningún resultado.');
}

// Todos los items de una misma corrida comparten los mismos timestamps de
// escaneo (vienen del mismo XML de Nmap), así que tomamos el primero.
const scanStartedAt = items[0].json.scanStartedAt;
const scanFinishedAt = items[0].json.scanFinishedAt;

// Hosts únicos detectados (por si en el futuro escaneamos un rango con
// varios hosts, no solo target1).
const uniqueHosts = new Set(items.map((i) => i.json.hostIp).filter(Boolean));

return [
  {
    json: {
      scanUuid: crypto.randomUUID(),
      targetRange: Array.from(uniqueHosts).join(', '),
      startedAt: scanStartedAt,
      finishedAt: scanFinishedAt,
      hostCount: uniqueHosts.size,
      findingCount: items.length,
    },
  },
];

parameters.query:
INSERT INTO scan_history (scan_uuid, target_range, started_at, finished_at, host_count, finding_count, status)
VALUES ($1, $2, $3, $4, $5, $6, 'completed')
RETURNING id;

